75	impl<'a> MayHaveSideEffects<'a> for IdentifierReference<'a> {
76	    fn may_have_side_effects(&self, ctx: &impl MayHaveSideEffectsContext<'a>) -> bool {
77	        match self.name.as_str() {
78	            "NaN" | "Infinity" | "undefined" => false,
79	            // Reading global variables may have a side effect.
80	            // NOTE: It should also return true when the reference might refer to a reference value created by a with statement
81	            // NOTE: we ignore TDZ errors
82	            _ => {
83	                ctx.unknown_global_side_effects()
84	                    && ctx.is_global_reference(self)
85	                    && !is_known_global_identifier(self.name.as_str())
86	            }
87	        }
88	    }
89	}
