102	impl<'a> MayHaveSideEffects<'a> for UnaryExpression<'a> {
103	    fn may_have_side_effects(&self, ctx: &impl MayHaveSideEffectsContext<'a>) -> bool {
104	        match self.operator {
105	            UnaryOperator::Delete => true,
106	            UnaryOperator::Void | UnaryOperator::LogicalNot => {
107	                self.argument.may_have_side_effects(ctx)
108	            }
109	            UnaryOperator::Typeof => {
110	                if matches!(&self.argument, Expression::Identifier(_)) {
111	                    false
112	                } else {
113	                    self.argument.may_have_side_effects(ctx)
114	                }
115	            }
116	            UnaryOperator::UnaryPlus => {
117	                // ToNumber throws an error when the argument is Symbol / BigInt / an object that
118	                // returns Symbol or BigInt from ToPrimitive
119	                self.argument.to_primitive(ctx).is_symbol_or_bigint() != Some(false)
120	                    || self.argument.may_have_side_effects(ctx)
121	            }
122	            UnaryOperator::UnaryNegation | UnaryOperator::BitwiseNot => {
123	                // ToNumeric throws an error when the argument is Symbol / an object that
124	                // returns Symbol from ToPrimitive
125	                self.argument.to_primitive(ctx).is_symbol() != Some(false)
126	                    || self.argument.may_have_side_effects(ctx)
127	            }
128	        }
129	    }
130	}
