83	pub fn maybe_object_with_to_primitive_related_properties_overridden(
84	    obj: &ObjectExpression<'_>,
85	) -> bool {
86	    obj.properties.iter().any(|prop| match prop {
87	        ObjectPropertyKind::ObjectProperty(prop) => match &prop.key {
88	            PropertyKey::StaticIdentifier(id) => {
89	                matches!(id.name.as_str(), "toString" | "valueOf")
90	            }
91	            PropertyKey::PrivateIdentifier(_) => false,
92	            PropertyKey::StringLiteral(str) => {
93	                matches!(str.value.as_str(), "toString" | "valueOf")
94	            }
95	            PropertyKey::TemplateLiteral(temp) => temp
96	                .single_quasi()
97	                .is_some_and(|val| matches!(val.as_str(), "toString" | "valueOf")),
98	            _ => true,
99	        },
100	        ObjectPropertyKind::SpreadProperty(e) => match &e.argument {
101	            Expression::ObjectExpression(obj) => {
102	                maybe_object_with_to_primitive_related_properties_overridden(obj)
103	            }
104	            Expression::ArrayExpression(_)
105	            | Expression::StringLiteral(_)
106	            | Expression::TemplateLiteral(_) => false,
107	            _ => true,
108	        },
109	    })
110	}
