/// Whether a `String(value)` / `new String(value)` call may have side effects.
///
/// `ToString` is applied to the argument, which calls `ToPrimitive` on object-like/unknown
/// values and can execute user-defined coercion code (`toString`/`valueOf`/`Symbol.toPrimitive`).
/// Known primitive arguments and plain object literals (without a custom string conversion method)
/// are safe.
fn string_wrapper_may_have_side_effects<'a>(
    args: &[Argument<'a>],
    ctx: &impl MayHaveSideEffectsContext<'a>,
) -> bool {
    if args.iter().any(|e| e.may_have_side_effects(ctx)) {
        return true;
    }
    args.first().is_some_and(|arg| {
        arg.as_expression().is_none_or(|expr| expr.to_primitive(ctx).is_string().is_none())
    })
}

