/// `ToNumber` throws on Symbol and can execute user code during `ToPrimitive`.
/// Known primitive arguments and plain object literals (without a custom numeric conversion method)
/// are safe.
fn number_wrapper_may_have_side_effects<'a>(
    args: &[Argument<'a>],
    ctx: &impl MayHaveSideEffectsContext<'a>,
) -> bool {
    if args.iter().any(|e| e.may_have_side_effects(ctx)) {
        return true;
    }
    args.first().is_some_and(|arg| {
        arg.as_expression().is_none_or(|expr| expr.to_primitive(ctx).is_symbol() != Some(false))
