/// Whether a `new Date(...)` call may have side effects.
///
/// Pure with no arguments, or when every argument is a numeric or string literal.
/// An unknown variable reference could be an object that invokes user-defined coercion code.
fn new_date_may_have_side_effects<'a>(
    args: &[Argument<'a>],
    ctx: &impl MayHaveSideEffectsContext<'a>,
) -> bool {
    if args.iter().any(|e| e.may_have_side_effects(ctx)) {
        return true;
    }
    !args.iter().all(|arg| {
        arg.as_expression().is_some_and(|expr| {
            matches!(expr, Expression::NumericLiteral(_) | Expression::StringLiteral(_))
        })
    })
}

