fn new_buffer_may_have_side_effects<'a>(
    args: &[Argument<'a>],
    ctx: &impl MayHaveSideEffectsContext<'a>,
) -> bool {
    if args.iter().any(|e| e.may_have_side_effects(ctx)) {
        return true;
    }
    !args.iter().all(|arg| {
        arg.as_expression().is_some_and(|expr| matches!(expr, Expression::NumericLiteral(_)))
