            | PropertyKey::PrivateIdentifier(_)
            | PropertyKey::StringLiteral(_)
            | PropertyKey::NumericLiteral(_) => false,
            PropertyKey::TemplateLiteral(temp) => temp.single_quasi().is_none(),
            // Computed keys could be `[Symbol.iterator]`.
            _ => true,
        },
        // Spreading an object could copy an own enumerable `Symbol.iterator`.
        ObjectPropertyKind::SpreadProperty(_) => true,
    })
