313	/// Whether a `String(value)` / `new String(value)` call may have side effects.
314	///
315	/// `ToString` is applied to the argument, which calls `ToPrimitive` on object-like/unknown
316	/// values and can execute user-defined coercion code (`toString`/`valueOf`/`Symbol.toPrimitive`).
317	/// Known primitive arguments and plain object literals (without a custom string conversion method)
318	/// are safe.
319	fn string_wrapper_may_have_side_effects<'a>(
320	    args: &[Argument<'a>],
321	    ctx: &impl MayHaveSideEffectsContext<'a>,
322	) -> bool {
323	    if args.iter().any(|e| e.may_have_side_effects(ctx)) {
324	        return true;
325	    }
326	    args.first().is_some_and(|arg| {
327	        arg.as_expression().is_none_or(|expr| expr.to_primitive(ctx).is_string().is_none())
328	    })
329	}
