413	            | PropertyKey::PrivateIdentifier(_)
414	            | PropertyKey::StringLiteral(_)
415	            | PropertyKey::NumericLiteral(_) => false,
416	            PropertyKey::TemplateLiteral(temp) => temp.single_quasi().is_none(),
